import{_ as a,c as t,o as i,ah as n,ay as r}from"./chunks/framework.dmO2K83R.js";const f=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"intro.md","filePath":"intro.md","lastUpdated":1759432097000}'),o={name:"intro.md"};function s(l,e,c,p,d,h){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h1><p>Waylis is a Node.js package designed to simplify and speed up interaction between the user and your applications. It’s an all-in-one solution offering both a developer-friendly API and a user-friendly web UI.</p><p><img src="'+r+'" alt="Promo"></p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to “Motivation”">​</a></h2><p>Traditional <a href="https://en.wikipedia.org/wiki/Client%E2%80%93server_model" target="_blank" rel="noreferrer">client-server</a> applications often require building a separate <a href="https://en.wikipedia.org/wiki/Front-end_web_development" target="_blank" rel="noreferrer">frontend</a>: designing forms, input flows, and UI components just to collect, validate and display data. Waylis eliminates this extra work by offering a ready-to-use web interface where interaction happens throw predefined chat scenes. The user and your application communicate using simple messages, which can contain data of different formats: from plain text to entire files.</p><p>This approach makes it easy to prototype ideas, create demos, or even run production-ready services without writing a single line of frontend code.</p><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to “Use cases”">​</a></h2><p>The scope of Waylis is quite broad. You can use it to build entirely new applications from scratch, or integrate it into existing ones to provide a specific part of the functionality.</p><ul><li>Desktop tools packaged into a <a href="https://nodejs.org/api/single-executable-applications.html" target="_blank" rel="noreferrer">single executable file</a>.</li><li>Public online services (for example: converters, generators, calculators).</li><li>Internal systems for companies.</li><li>Demonstration setups for showcasing specific logic.</li><li>Utilities for personal use.</li><li>and more...</li></ul><h2 id="technical-overview" tabindex="-1">Technical overview <a class="header-anchor" href="#technical-overview" aria-label="Permalink to “Technical overview”">​</a></h2><p>At its core, Waylis runs as an HTTP server with its own built-in frontend and backend parts. In the backend, it uses a chat scene engine that lets users interact with the application just like a <a href="https://en.wikipedia.org/wiki/Chatbot" target="_blank" rel="noreferrer">chatbot</a>.</p><p>The entire flow is based on message exchange between the user and your app:</p><ul><li><p>Users start communication by sending predefined command messages that trigger a corresponding scene.</p></li><li><p>Each scene can define its own sequence of steps, where the user is asked questions to collect specific data.</p></li><li><p>Once all steps are completed, the scene handler is executed. At this point, the handler has access to all user-provided data and can run custom logic on it.</p></li></ul><p>Waylis can use any database and file storage to store data. All you need to do is implement the appropriate interfaces.</p>',14)])])}const m=a(o,[["render",s]]);export{f as __pageData,m as default};
